SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(d),'extension',to_jsonb(e),'identity',to_jsonb(pg_identify_object(d.classid,d.objid,d.objsubid)),'address',to_jsonb(pg_identify_object_as_address(d.classid,d.objid,d.objsubid))) ORDER BY e.oid,d.classid,d.objid,d.objsubid),'[]'::jsonb) AS payload FROM pg_depend d JOIN pg_extension e ON e.oid=d.refobjid WHERE d.refclassid='pg_extension'::regclass AND d.deptype='e') AS capture